def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    op_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            op_c += 1
    op_d = n - op_c

    if op_c == 0:
        return 'D'

    last_me = history[n - 1][0]
    last_op = history[n - 1][1]

    if n < 30:
        last = last_op
        run = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == last:
                run += 1
            else:
                break

        if last_op == 'D':
            if run >= 2 or op_d * 3 > n:
                return 'D'
            if last_me == 'D':
                return 'C'
            return 'D'

        if op_d * 2 > n:
            return 'D'
        return 'C'

    if n == 99:
        return 'D'

    prior_p = [0.85, 0.30, 0.22, 0.18]
    prior_total = 5.0

    c = [0.0, 0.0, 0.0, 0.0]
    t = [0.0, 0.0, 0.0, 0.0]
    for i in range(4):
        c[i] = prior_p[i] * prior_total
        t[i] = prior_total

    w = 1.0
    for i in range(n - 1, 0, -1):
        a0, b0 = history[i - 1]
        if a0 == 'C':
            idx = 0 if b0 == 'C' else 1
        else:
            idx = 2 if b0 == 'C' else 3

        if history[i][1] == 'C':
            c[idx] += w
        t[idx] += w
        w *= 0.9

    p0 = c[0] / t[0]
    p1 = c[1] / t[1]
    p2 = c[2] / t[2]
    p3 = c[3] / t[3]

    v0 = 0.0
    v1 = 0.0
    v2 = 0.0
    v3 = 0.0

    future = 100 - n - 1
    for _ in range(future):
        nc0 = 3.0 * p0 + p0 * v0 + (1.0 - p0) * v1
        nd0 = 1.0 + 4.0 * p0 + p0 * v2 + (1.0 - p0) * v3
        nv0 = nc0 if nc0 >= nd0 else nd0

        nc1 = 3.0 * p1 + p1 * v0 + (1.0 - p1) * v1
        nd1 = 1.0 + 4.0 * p1 + p1 * v2 + (1.0 - p1) * v3
        nv1 = nc1 if nc1 >= nd1 else nd1

        nc2 = 3.0 * p2 + p2 * v0 + (1.0 - p2) * v1
        nd2 = 1.0 + 4.0 * p2 + p2 * v2 + (1.0 - p2) * v3
        nv2 = nc2 if nc2 >= nd2 else nd2

        nc3 = 3.0 * p3 + p3 * v0 + (1.0 - p3) * v1
        nd3 = 1.0 + 4.0 * p3 + p3 * v2 + (1.0 - p3) * v3
        nv3 = nc3 if nc3 >= nd3 else nd3

        v0 = nv0
        v1 = nv1
        v2 = nv2
        v3 = nv3

    if last_me == 'C':
        if last_op == 'C':
            p = p0
        else:
            p = p1
    else:
        if last_op == 'C':
            p = p2
        else:
            p = p3

    val_c = 3.0 * p + p * v0 + (1.0 - p) * v1
    val_d = 1.0 + 4.0 * p + p * v2 + (1.0 - p) * v3

    if val_d > val_c + 1e-9:
        return 'D'
    return 'C'
